      '休日の過ごし方を公開するとき、人は選ぶ。充実した一部の瞬間を選び、退屈な大半を削る。投稿される生活は、編集を経た見せ場の連続である。それ自体は悪くない。誰もが自分の生活を一番よく見せたいと願うだけだ。\n問題は、それを見る側の勘定だ。画面の向こうでは、友だちは毎週旅に出て、趣味に恵まれ、人間関係も円満にみえる。比較の対象は、他人の見せ場と、自分の丸ごとの生活。⟪編集された他人の断片と、編集されていない自分の全体とを比べるかぎり、負けるのは最初から決まっている⟫。負け続ける勘定を毎晩のように続ければ、自分の生活が「普通以下」に感じられても不思議ではない。\nでは、どうするか。投稿の中身を疑えと言いたいのではない。むしろ、見せ場の裏に必ずある「削られた大半」を思い出すことだ。旅の写真の裏には雨の日のホテルがあり、趣味の自慢の裏には続かなかった習い事がある。見えていないものを勘定に入れ直したとき、他人の生活は、比較に耐える大きさから急に小さくなる。',
