    passage:
      '校則の見直しの議論で、しばしば出される意見がある。「規則だから従うしかない」。確かに、社会には従うだけの規則がたくさんある。ただ、校則の議論では、その前に問うべきことがある。この規則は、何のためにあるのか、である。\n髪型を一律に定める規則には、かつて理由があったとされる。しかし、その理由——例えば「学業に専念させる」——が今も生きているかは、別の問題だ。⟪理由が死んだ規則は、形だけが残る⟫。形だけの規則を守らせる教育は、子どもに「理由より形式」を教える。理由を問う代わりに、従うことを美徳とする訓練である。\nだから私は、校則の見直しを「規則を減らすこと」とは考えない。問われるべきは規則の数ではなく、一つ一つの規則が理由を伴って生きているかどうかである。理由の語れる規則は、破られたときに理由ごと話し合える。理由の語れない規則は、守らせるときに力しか残らない。社会に出てから、みなを納得させる規則をつくる側に回るためにも、校則で理由と向き合う経験は、安くない財産になると考える。',
