    passage:
      '財布から千円札を出して支払うとき、手は少しためらう。出した分だけ財布が痩せるのが目で分かるからだ。この「支払いの痛み」は、金銭感覚のアラームとして働いてきた。ところが、タッチするだけの決済では、アラームは鳴らない。残高という数字が静かに減っていくだけで、使った実感は薄い。便利さの代金として、私たちは支出の実感を手放した。\n家計アプリの流行は、その裏返しだろう。減った実感がないからこそ、後から帳簿で確かめる必要が生じている。⟪実感をなくしたものは、後から数え直さなければ感じられなくなる⟫——支出についても、時間についても、通じる話である。時間の使い方を記録するアプリが増えたのも、同じ理由からかもしれない。\nだからといって、現金に戻れと言いたいのではない。道具はもう戻らない。問題は、使いすぎないための古いアラームが消えたなら、新しい確認の習慣を設計し直す必要がある、ということだ。週に一度、使った額を眺める十分間。小さな儀式でも、目で確かめる手順は、実感を取り戻す入口になる。',
