      '「よく休んで英気を養え」という言い方がある。休むことの価値を、その後の働きで支払わせる考え方だ。休養は仕事のための充電であり、充電が済めば速やかに放電に戻るべきである、と。\nこの考え方には、一つだけ盲点がある。休むことの価値を、完全に仕事の外に置けない人たちの存在だ。趣味に没頭し、ただ散歩し、何もせず昼寝する——そうした時間の多くは、次の仕事の役には立たない。立たないからこそ、人はその時間に、仕事との関連で自分を測り直すことから解放される。役に立たない時間がなければ、人は常に仕事の延長線上に立たされ続ける。\n⟪休養を「英気を養うこと」としか呼べない社会は、休むことすべてを仕事に貸し出してしまう⟫。休日を充電と呼び、充電を効率と呼ぶ言い方を借りているかぎり、完全に休めている人はいない。だから私は、役に立つかどうかで問われる前の、単なる休息を、休息として認める言葉を、もう一つ用意したほうがよいと思う。',
