    source: '本站原创模拟（非真题）',
    passage:
      '終活の講習会には、遺言書の書き方を学びに来る人が多い。多くの人は、相続の争いを避けるためと説明する。もっともな動機だが、遺言書の効用はそれだけではないと、経験者たちは口を揃える。\n遺言書を書こうとすると、まず自分の持ち物の目録から始まる。続いて、だれに何を残したいか。すると自然に、次の問いへ進む。あの土地に深い思い入れがあるのはなぜか。あまり会わない親戚の名前を、なぜ思い出したのか。遺言書は、処分の書類の形をした、自分史の下書きなのである。書き手は、残る側の顔を一人ずつ思い浮かべながら、自分がどんな関係の中で生きてきたかを、初めてきちんと眺める。\n遺言書とは、死亡の準備ではなく、生きた関係の棚卸しである。だから書き終えたあとの人の話は似ている。「相続の心配より、会いたくなった」と。書類としての効力が発動するのは最期の一瞬だが、書く過程の効力は、今この瞬間から効き始めている。',
