    passage:
      '災害のニュースを見る夜は、テレビの前で何かをしたくなる。募金、物資の送付、情報の拡散。手を動かすことは大切だ。だが、その夜の私たちの内面をもう少し観察してみる。遠くの悲劇に心を動かす力は、距離とともに急激に減衰する。国を越えると半減し、業種を越えるとまた半減する。同じ国内の水害でも、自分の通勤路が浸水した日と、知らない土地が浸水した日では、受け止め方がまるで違う。これを人の薄情と呼ぶのは、早すぎる。共感は資源であって、無尽蔵ではない。すべての悲劇に等しく心を振り絞っていたら、日常の仕事が成立しない。減衰そのものは、心の節約の正常な働きだ。\n問題は、減衰の落とし方である。遠くの悲劇への心の動員を、すべて「必要のない心がけ」に分類してしまうと、今度は近くの悲劇への感受性まで鈍る。共感は筋肉で、使わない部位から固まる。遠くの出来事に心を動かされた経験は、その筋肉の維持運動として、機能している面がある。\nもう一つ、距離の減衰には盲点がある。遠くと近くの境界は、実は流動的だ。今日は他人の土地だった水害が、十年後には自分の通勤路になる。災害の記録が示すのは、悲劇の場所の移動が、人それぞれの一生の尺度でも起こることだ。⟪遠くの悲劇への向き合い方は、そのまま、未来の自分への向き合い方の練習でもある⟫。\nだから私は、遠くのニュースに心を動かされた夜は、翌日ではなくその夜に、できることを一つだけ済ませることを勧める。金額の大小ではない。動いたという事実が、共感の筋肉を今日も使ったと体に記憶させる。その記憶のある体は、隣の階の悲報にも、前より早く気づく。',
