    source: '本站原创模拟（非真题）',
    passage:
      '子どもの習い事には、わかりやすい報酬が用意されている。上達の実感、級や資格、発表会の拍手。努力が形になって返ってくる仕組みが、最初から揃っている。ところが大人が習い事を始めると、この仕組みがすべて外れる。大人の稽古には、級がないことも多い。発表会はあっても、参加しない自由がある。上達のスピードは、子どもの頃より確実に遅い。では、大人の稽古の報酬は何か。\n外側の報酬が消えると、内側の報酬が残る。大人が稽古を続ける理由としてよく語られるのは、上達そのもの、同じ趣味の人との時間、そして、仕事とは別の自分の時間を持つことである。仕事の評価は他者が決める。稽古の上達の評価は、少なくとも一部は自分に残る。この「評価の持ち帰り」が、大人の稽古の静かな報酬だと思う。\n⟪大人の稽古とは、報われることを自分で定義し直す営みである⟫。子どもの習い事は、社会が用意した物差しで測られる。大人になると、その物差しは渡されない。自分で物差しを作り、自分で測る。この作業は、初めは不安である。測り方が合っているか、誰も保証しない。しかし慣れると、物差しを持つ感覚は稽古の外にも応用が利く。仕事でも生活でも、外の報酬の代わりに自分の物差しを立てられる人は、報われない期間を耐えられる。大人の稽古が教えてくれるのは、技芸の内容だけではない。',
